/* file : ErrorMapper.xml, id : saveErrorLog */
INSERT
  INTO TB_ERROR_LOG (
              MODEL_SEQ
            , AUGMENT_SEQ
            , ERR_TP
            , ERR_LCT
            , ERR_CN
            , ERR_NM
            , ERR_CD
            , REG_USER_SEQ
            , REG_IP
            )
       VALUES (
              #{modelSeq}
            , #{augmentSeq}
            , #{errTp}
            , #{errLct}
            , #{errCn}
            , #{errNm}
            , #{errCd}
            , #{loginUserSeq}
            , #{loginUserIp}
            )

mapper.select:
SELECT *
FROM TB_ERROR_LOG
WHERE MODEL_SEQ = #{etcModelSeq}
  AND ERR_LCT = #{ERROR_LCT}
ORDER BY REG_DT DESC
LIMIT 1
